-- Reset before seeding so that re-applying this file is idempotent.
TRUNCATE TABLE
  payments, billing_items, billing_encounters, patient_insurance,
  cds_alerts, imaging_orders, lab_results, lab_orders,
  prescription_items, prescriptions, admissions, diagnoses, vital_signs,
  encounters, patient_family_history, patient_medical_history,
  patient_allergies, patients, drug_interactions, allergen_catalog,
  medication_catalog, providers, icd10_codes, counties, insurance_providers
  RESTART IDENTITY CASCADE;

-- Counties (20) — Kenyan county lookup for patient origin

-- ICD-10 codes (20) — diagnosis code reference

-- Providers (20) — clinicians, nurses, pharmacists, etc.

-- Medication catalog (15) — drugs available to prescribe

-- Allergen catalog (12) — allergens with cross-reactivity notes

-- Drug interactions (6) — clinically significant pairs

-- Insurance providers (8) — NHIF, private, corporate, micro

-- Patients (60)

-- Patient allergies (66) — 0–2 per patient, → allergen_catalog

-- Patient medical history (81) — chronic/past conditions

-- Patient family history (62) — relation + condition

-- Patient insurance (45) — ~85% of patients, → insurance_providers

-- Encounters (120) — one clinical visit each, 2 per patient

-- Vital signs (120) — one set per encounter (BMI is a generated column)

-- Diagnoses (120) — ICD-10 coded, one per encounter

-- Admissions (49) — one per inpatient/emergency encounter (LOS is generated)

-- Prescriptions (72) — Rx headers; items follow below

-- Prescription items (120) — 1–2 medications per prescription

-- Lab orders (66) — ordered panels; per-test results follow below

-- Lab results (74) — per-test values for each lab order (~20% abnormal)

-- Imaging orders (60) — X-Ray, CT, MRI, Ultrasound, Echo, Mammography

-- CDS alerts (60) — drug-interaction / allergy / renal / critical-result

-- Billing encounters (72) — one bill per ~60% of encounters (KES)

-- Billing items (133) — line items per bill (consultation, lab, pharmacy, …)

-- Payments (122) — insurance + patient settlement (cash/M-Pesa/bank/…)

